// Recover only quote-rendering differences from the captured direct-user text.
// The backend still receives the exact original substring and validates target,
// revision and consent. Never repair words, negation, paths or a missing source.
function notificationQuote(quote,sources){
 if(typeof quote!=='string'||sources.some(s=>s.text.includes(quote)))return quote;
 const wanted=quote.replace(/\\"/g,'"').replace(/[“”]/g,'"');
 if(!wanted||!wanted.includes('"'))return quote;
 const matches=new Set();
 for(const {text}of sources){const plain=text.replace(/[“”]/g,'"');let at=plain.indexOf(wanted);while(at!==-1){matches.add(text.slice(at,at+wanted.length));at=plain.indexOf(wanted,at+1);}}
 return matches.size===1?[...matches][0]:quote;
}

